-- Colors (was colors.conf)
-- GENERATED by matugen from ~/.config/matugen/templates/hyprland/colors.lua into
-- ~/.local/state/quickshell/user/generated/hyprland/colors.lua. hypr/hyprland/colors.lua loads it.
-- Edit the template, not this file.

hl.config({
    general = {
        col = {
            active_border   = "rgba({{colors.outline.default.hex_stripped}}AA)",
            inactive_border = "rgba({{colors.outline_variant.default.hex_stripped}}AA)",
        },
    },

    misc = {
        background_color = "rgba({{colors.surface.dark.hex_stripped}}FF)",
    },
})

-- hyprbars settings + buttons (R -> L). Only applied if the plugin is loaded,
-- so the config doesn't error out when hyprbars isn't installed.
-- Note: button actions must use the new Lua dispatch syntax.
if hl.plugin and hl.plugin.hyprbars then
    hl.config({
        plugin = {
            hyprbars = {
                bar_text_font              = "Rubik, Geist, AR One Sans, Reddit Sans, Inter, Roboto, Ubuntu, Noto Sans, sans-serif",
                bar_height                 = 30,
                bar_padding                = 10,
                bar_button_padding         = 5,
                bar_precedence_over_border = true,
                bar_part_of_window         = true,

                bar_color = "rgba({{colors.background.default.hex_stripped}}FF)",
                col = {
                    text = "rgba({{colors.on_background.default.hex_stripped}}FF)",
                },
            },
        },
    })

    hl.plugin.hyprbars.add_button({
        bg_color = "rgb({{colors.on_background.default.hex_stripped}})",
        fg_color = "rgb({{colors.background.default.hex_stripped}})",
        size     = 13,
        icon     = "󰖭",
        action   = [[hyprctl dispatch 'hl.dsp.window.close()']],
    })
    hl.plugin.hyprbars.add_button({
        bg_color = "rgb({{colors.on_background.default.hex_stripped}})",
        fg_color = "rgb({{colors.background.default.hex_stripped}})",
        size     = 13,
        icon     = "󰖯",
        action   = [[hyprctl dispatch 'hl.dsp.window.fullscreen({ mode = "maximized" })']],
    })
    hl.plugin.hyprbars.add_button({
        bg_color = "rgb({{colors.on_background.default.hex_stripped}})",
        fg_color = "rgb({{colors.background.default.hex_stripped}})",
        size     = 13,
        icon     = "󰖰",
        action   = [[hyprctl dispatch 'hl.dsp.window.move({ workspace = "special:special", follow = false })']],
    })
end

-- Pinned windows get a special border
hl.window_rule({
    name  = "pinned-border",
    match = { pin = true },
    border_color = "rgba({{colors.primary.default.hex_stripped}}AA) rgba({{colors.primary.default.hex_stripped}}77)",
})
